query productsQuery($first: Int, $after: String, $query: String!) {
  products(query: $query, after: $after, first: $first) {
    edges {
      node {
        id
        _id
        uid
        slug
        title
        description
        notice_text
        price
        sku
        file_id
        compare_at_price
        product_type
        thumbnail {
          id
          path
        }
        file {
          id
          title
          size
          path
        }
        tags {
          id
          title
        }
        variants {
          id
          price
          compare_at_price
          sku
          enable_inventory_limit
          inventory_quantity
        }
        inventory_quantity
        enable_inventory_limit
        created_at
        updated_at
      }
      cursor
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}

query productQuery($id: ID!) {
  product: node(id: $id) {
    __typename
    ... on Product {
      __typename
      id
      _id
      uid
      slug
      title
      description
      notice_text
      updated_at
      price
      sku
      file_id
      compare_at_price
      product_type
      shipping_group_id
      price_bundle_id
      thumbnail {
        id
        path
      }
      file {
        id
        title
        size
        path
      }
      options {
        id
        label
        options
        type
        options_types {
          option_id
          value
        }
      }
      tags {
        id
        title
      }
      images_ids
      variants {
        id
        price
        file_id
        image_id
        compare_at_price
        sku
        options {
          option_id: id
          value
        }
        enable_inventory_limit
        inventory_quantity
      }
      order_bump {
        id
        title
        price
        sku
        enabled
        compare_at_price
        description
        image_id
        file_id
      }
      order_bumps {
        id
        order_bump_product_id
        variant_id
        is_checked
        product {
          id
          uid
          title
          description
          price
          compare_at_price
          sku
          file_id
        }
      }
      features {
        id
        title
        description
        image_id
      }
      testimonials {
        id
        name
        position
        comment
        image_id
      }
      faq {
        id
        question
        answer
      }
      enable_custom_options
      custom_options {
        id
        type
        name
        placeholder
      }
      price_bundle {
        id
        items {
          id
          label
          quantity
          discount_value
          discount_type
        }
      }
      default_variant {
        id
        uid: id
        file_uid: file_id
        _id
        price
        image {
          id
          path
        }
        compare_at_price
        sku
      }
      inventory_quantity
      enable_inventory_limit
      funnels {
        id
        uid: id
        name
        slug
      }
      stores {
        id
        uid: id
        name
        slug
      }
      created_at
    }
  }
}

query ordersQuery($first: Int, $after: String, $query: String!) {
  orders(first: $first, after: $after, query: $query) {
    edges {
      node {
        id
        _id
        name
        total
        fulfillment_status
        financial_status
        customer {
          full_name
          id
        }
        cancelled_at
        date: created_at
        formattedDate: created_at(format: "LLL")
        test
        currency
        checkout {
          id
          store {
            id
            name
          }
          funnel {
            id
            name
          }
        }
        tags
      }
      cursor
    }
    pageInfo {
      endCursor
      hasNextPage
      hasPreviousPage
      startCursor
    }
  }
}

mutation cancelOrderMutation($id: ID!, $reason: String!, $notifyCustomer: Boolean!, $refund: Boolean!) {
  cancelOrder(id: $id, reason: $reason, notifyCustomer: $notifyCustomer, refund: $refund) {
    id
    _id
    name
    cancelled_at
    financial_status
    fulfillment_status
  }
}

query CustomerQuery($id: ID!) {
  node(id: $id) {
    ... on Customer {
      id
      _id
      first_name
      last_name
      full_name
      email
      phone
      avatar
      location
      expenses
      orders_count
      created_at
      updated_at
    }
  }
}

query customersQuery($first: Int, $after: String, $query: String!) {
  customers(first: $first, after: $after, query: $query) {
    edges {
      node {
        id
        _id
        avatar
        email
        full_name
        phone
        updated_at
        created_at
        location
      }
      expenses
      orders_count
      cursor
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}

query FunnelQuery($id: ID!) {
  node(id: $id) {
    ... on Funnel {
      id
      _id
      name
      slug
      published
      created_at
      updated_at
    }
  }
}
